#!/usr/bin/env bun
// Generated by minsky compile. Do not edit directly.
// Source: .minsky/hooks/retrospective-completeness-detector.ts

// UserPromptSubmit hook: when the just-completed turn produced retrospective-shaped
// work, check that the sections `/retrospective`'s output format REQUIRES at the
// declared triage level are actually present — and that every cited structural-fix
// task had its status read in-turn (the skill's Step 5 liveness check).
//
// LOG-ONLY (mt#3601). Writes a calibration record; never injects, never blocks.
// Graduation to injection is a separate decision once the FP rate is measured.
//
// Why this exists: the skill's output format is prose the agent is trusted to
// produce, and nothing verifies it. A retrospective missing `### Verification`,
// the family `### Escalation`, and every liveness check is indistinguishable —
// to every mechanism in this repo — from a complete one. Both known recurrences
// were caught by the principal rather than by the system:
//   R1 2026-06-28 (mem#598) — 7 Supabase-incident retros compressed to the Minor
//      format, including a Repeated failure and a large-family member.
//   R2 2026-08-03 (mem#826) — four retros off the mt#3092 outage written as
//      narrative memos (mem#822, mem#823); one ASSERTED family membership without
//      running the count or the liveness check.
// R1's fix shipped at memory tier and did not contain R2, which is why this is a
// detector rather than another prose reminder.
//
// Event placement per ADR-031 (`adr-031-guidance-detector-lifecycle-event.md`):
// this detector is TOOL-INSPECTING — it reads the turn's `tool_use` blocks to
// know whether `/retrospective` was invoked and whether `tasks_status_get` /
// `tasks_get` was called for each cited task — so it runs at `UserPromptSubmit`,
// where the transcript has had the most flush time, NOT at `Stop`, where it has
// had the least. It slices against the Stop-recorded anchor when one exists and
// degrades to the shared resolver when it does not.
//
// Mechanism per ADR-024: that ADR's ladder scopes itself to detectors matching
// paraphrasable TRIGGER PHRASES, where recall misses drive the rungs. This
// detector matches section HEADINGS whose exact text the skill mandates, so
// there is no recall axis to widen and Rung 2 does not apply. Two of its
// cross-cutting invariants DO apply and are honored: a scan that cannot complete
// records a `degraded` marker rather than silently passing, and the calibration
// record carries `source: "live"` for the coverage-receipt done-gate.
//
// @see .claude/skills/retrospective/SKILL.md — the required-section contract
// @see .minsky/hooks/retrospective-trigger-scanner.ts — sibling: whether a retro FIRES
// @see mem#598 — family root `retrospective-under-run`
// @see mt#3602 — the sibling tooling gap (memory_patch) from the same incident

import type { ClaudeHookInput } from "./types";
import { extractLastAssistantTurn, extractAssistantText } from "./transcript";
import type { TranscriptLine } from "./transcript";
import type { DispatchContext, GuardOutcome } from "./registry";
import { hasRetrospectiveSkillInvocation } from "./retrospective-trigger-scanner";

export const OVERRIDE_ENV_VAR = "MINSKY_SKIP_RETRO_COMPLETENESS";

// ---------------------------------------------------------------------------
// Triage levels + their required section sets
// ---------------------------------------------------------------------------

export type TriageLevel = "minor" | "process" | "repeated" | "unknown";

/**
 * Sections the skill requires at EVERY triage level.
 *
 * `### Triage` alone: the compressed (Minor) format is a legitimate output
 * shape, and demanding the full set of it is exactly the over-fire that would
 * make this detector noise. What is NOT legitimate at any level is failing to
 * declare which level was chosen — that is the decision the rest keys off.
 */
export const ALWAYS_REQUIRED = ["Triage"] as const;

/** Additional sections required at `Process failure` / `Repeated failure`. */
export const FULL_REQUIRED = [
  "Incident",
  "Agent error",
  "Failure mode",
  "Root cause",
  "Recurrence check",
  "Fixes",
  "Verification",
] as const;

/** Required additionally at `Repeated failure`, or when a family count >= 3 is stated. */
export const ESCALATION_REQUIRED = ["Escalation"] as const;

/**
 * Markers that the turn produced retrospective-shaped output even though the
 * Skill tool was not the trigger (e.g. the agent wrote the report directly).
 * Deliberately narrow: a `##`/`###` heading, not a bare mention of the word.
 */
// Heading depth is `#{2,3}`, not `#{3}`, deliberately: mem#823 — the very
// artifact this detector exists to catch — writes `## Root cause` at depth 2.
// A depth-3-only pattern missed the motivating case, which the AT5 test caught.
export const RETRO_SHAPE_PATTERNS: RegExp[] = [
  /^#{2,3}\s+Retrospective\b/im,
  /^#{2,3}\s+Root cause\b/im,
  /^#{2,3}\s+Failure mode\b/im,
];

/**
 * Heading depth accepted for a section, used by BOTH `hasSection` and
 * `TRIAGE_SECTION` (PR #2564 R1).
 *
 * These two must agree. They did not: `hasSection` accepted `#{2,4}` while the
 * triage parse required exactly `#{3}`, so a retrospective writing `## Triage`
 * was simultaneously "has a Triage section" (not reported missing) and
 * "declared no triage level" (silently escalated to the full required set).
 * That combination is the worst of both — the agent is told nothing is missing
 * while being graded against the strictest bar.
 */
const HEADING_DEPTH = "#{2,4}";

const TRIAGE_SECTION = new RegExp(`^${HEADING_DEPTH}\\s+Triage\\b([\\s\\S]{0,400})`, "im");

/**
 * A family recurrence count stated in prose, e.g. "Recurrence count: 5" or
 * "this is R5 of". Used to fire the Escalation requirement even when the
 * declared triage is not literally "Repeated failure" — the skill mandates
 * Escalation at >= 3 recurrences independent of the triage word.
 */
const FAMILY_COUNT_PATTERNS: RegExp[] = [
  /recurrence count\*{0,2}:?\s*\*{0,2}\s*(\d+)/i,
  /\bthis (?:incident )?is\s+\*{0,2}R(\d+)\b/i,
  /\bfamily .{0,60}?\bis\s+R(\d+)\b/i,
];

const ESCALATION_COUNT_THRESHOLD = 3;

// ---------------------------------------------------------------------------
// Detection
// ---------------------------------------------------------------------------

export function hasRetrospectiveShape(text: string): boolean {
  return RETRO_SHAPE_PATTERNS.some((re) => re.test(text));
}

export function parseTriageLevel(text: string): TriageLevel {
  const m = TRIAGE_SECTION.exec(text);
  if (!m) return "unknown";
  const body = (m[1] ?? "").toLowerCase();
  // Order matters: "repeated" is checked first because a Repeated-failure
  // triage line commonly also contains the words "process failure".
  if (body.includes("repeated failure")) return "repeated";
  if (body.includes("process failure")) return "process";
  if (body.includes("minor correction")) return "minor";
  return "unknown";
}

/** Highest family-recurrence count stated anywhere in the output, or 0. */
export function statedFamilyCount(text: string): number {
  let max = 0;
  for (const re of FAMILY_COUNT_PATTERNS) {
    const m = re.exec(text);
    if (m?.[1]) {
      const n = Number.parseInt(m[1], 10);
      if (Number.isFinite(n) && n > max) max = n;
    }
  }
  return max;
}

/** A `### <Name>` heading is present (matched on the heading, not a prose mention). */
export function hasSection(text: string, name: string): boolean {
  const escaped = name.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  return new RegExp(`^${HEADING_DEPTH}\\s+${escaped}\\b`, "im").test(text);
}

export function requiredSectionsFor(level: TriageLevel, familyCount: number): string[] {
  const required: string[] = [...ALWAYS_REQUIRED];
  // `unknown` is treated as the FULL set deliberately. An output that produced
  // retrospective-shaped headings but never declared a triage level has skipped
  // Step 0.5, and the compressed format is only defensible as an explicit call.
  if (level === "process" || level === "repeated" || level === "unknown") {
    required.push(...FULL_REQUIRED);
  }
  if (level === "repeated" || familyCount >= ESCALATION_COUNT_THRESHOLD) {
    required.push(...ESCALATION_REQUIRED);
  }
  return required;
}

/** Task ids the output cites as structural-fix targets. */
export function citedTaskIds(text: string): string[] {
  const ids = new Set<string>();
  for (const m of text.matchAll(/\bmt#(\d+)\b/g)) {
    ids.add(`mt#${m[1]}`);
  }
  return [...ids];
}

/**
 * Task ids whose status was actually READ in this turn — a `tasks_status_get`
 * or `tasks_get` tool call naming the id. This is the Step 5 liveness check,
 * checked against tool-call STATE rather than against prose claiming it ran.
 */
export function taskIdsWithStatusRead(turnLines: TranscriptLine[]): Set<string> {
  const read = new Set<string>();
  const LIVENESS_TOOLS = /(?:tasks_status_get|tasks_get)$/;

  // `taskId` is the declared param on both tools today. `task` is accepted as
  // well (PR #2564 R1): several sibling session_* tools spell the same argument
  // that way, and the failure mode of guessing wrong is asymmetric — a missed
  // field reports "you never checked this task's status" at an agent that did,
  // which is the false positive most likely to get the whole detector ignored.
  const ID_FIELDS = ["taskId", "task"] as const;

  const consider = (name: unknown, input: unknown): void => {
    if (typeof name !== "string" || !LIVENESS_TOOLS.test(name)) return;
    const record = input as Record<string, unknown> | undefined;
    if (!record) return;
    for (const field of ID_FIELDS) {
      const value = record[field];
      if (typeof value === "string" && value.length > 0) read.add(value);
    }
  };

  for (const line of turnLines) {
    if (line.type === "tool_use") {
      consider(line.name ?? line.tool_name, line.input);
    }
    const content = line.message?.content;
    if (Array.isArray(content)) {
      for (const block of content as Array<Record<string, unknown>>) {
        if (block["type"] === "tool_use") {
          consider(block["name"], block["input"]);
        }
      }
    }
  }
  return read;
}

export interface CompletenessFinding {
  triage: TriageLevel;
  familyCount: number;
  missingSections: string[];
  /** Cited fix-task ids with no in-turn status read (Step 5 liveness gap). */
  unverifiedTaskIds: string[];
}

export function analyze(text: string, turnLines: TranscriptLine[]): CompletenessFinding {
  const triage = parseTriageLevel(text);
  const familyCount = statedFamilyCount(text);
  const required = requiredSectionsFor(triage, familyCount);
  const missingSections = required.filter((name) => !hasSection(text, name));

  const readIds = taskIdsWithStatusRead(turnLines);
  const unverifiedTaskIds = citedTaskIds(text).filter((id) => !readIds.has(id));

  return { triage, familyCount, missingSections, unverifiedTaskIds };
}

// ---------------------------------------------------------------------------
// Hook entry point
// ---------------------------------------------------------------------------

export async function run(
  input: ClaudeHookInput,
  ctx: DispatchContext
): Promise<GuardOutcome | null> {
  const overrideVal = process.env[OVERRIDE_ENV_VAR];
  const isOverride =
    overrideVal === "1" ||
    overrideVal?.toLowerCase() === "true" ||
    overrideVal?.toLowerCase() === "yes";

  if (isOverride) {
    return {
      auditLines: [
        `[retrospective-completeness-detector] OVERRIDE: ack=${overrideVal} session=${input.session_id ?? "unknown"} ts=${new Date().toISOString()}\n`,
      ],
    };
  }

  if (!input.transcript_path) return null;

  try {
    // Read INSIDE the try (PR #2564 R1). This access used to sit above the
    // try, so a throwing `transcriptLines` accessor escaped the degraded
    // branch and propagated out of the guard entirely — the one failure the
    // fail-to-degraded invariant most needs to cover, and the only one it did
    // not. Surfaced by the AT7 test, which could not reach the branch at all.
    const lines = ctx.transcriptLines;
    if (lines.length === 0) return null;

    const turnLines = extractLastAssistantTurn(lines, ctx.recordedAnchor);
    if (turnLines.length === 0) return null;

    const text = extractAssistantText(turnLines);

    // Trigger: the Skill was invoked, OR the output is retrospective-shaped.
    // The tool-call signal is primary — it keys on STATE, not on wording, so a
    // retrospective that produced almost no prose still counts.
    const skillInvoked = hasRetrospectiveSkillInvocation(turnLines);
    if (!skillInvoked && !hasRetrospectiveShape(text)) return null;

    const finding = analyze(text, turnLines);
    if (finding.missingSections.length === 0 && finding.unverifiedTaskIds.length === 0) {
      return null;
    }

    // LOG-ONLY: calibration record, no `additionalContext`. The FP rate has to
    // be measured before this is allowed to spend the agent's attention.
    return {
      calibration: {
        source: "live",
        timestamp: new Date().toISOString(),
        session_id: input.session_id,
        triggered_by: skillInvoked ? "skill-invocation" : "output-shape",
        triage: finding.triage,
        family_count: finding.familyCount,
        missing_sections: finding.missingSections,
        unverified_task_ids: finding.unverifiedTaskIds,
      },
    };
  } catch (err) {
    // ADR-024 cross-cutting invariant: fail to a recorded `degraded` result,
    // never a silent skip. A scan that cannot run must be distinguishable from
    // a turn that was genuinely complete.
    return {
      calibration: {
        source: "live",
        timestamp: new Date().toISOString(),
        session_id: input.session_id,
        degraded: err instanceof Error ? err.message : String(err),
      },
    };
  }
}
